/**
 * Theories of cancer (17 Sept 2026, roadmap row 125): what cancer fundamentally is, according to each school of
 * thought, and how the schools connect. One `term` record per theory (claim, proposers, evidence for and against,
 * predictions that held or failed, therapies that came from it, and a closing "Status:" paragraph reading
 * established, partly confirmed, contested or superseded), plus one `pathway` hub that draws the theories as a
 * map: solid arrows are "feeds into", inhibiting arrows are "challenges". Registered in src/data/index.ts as
 * theoryHub and theoryTerms; listed on /mechanics/ in the "Theories of cancer" section. Every DOI here was
 * checked against Europe PMC before it was written down; where a primary paper has no DOI it is named, not linked.
 */
import type { PathwayInput, TermInput } from "@/lib/schema";

const asOf = "2026-09-17";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
const doi = (d: string, label: string) => ({ label, url: `https://doi.org/${d}` });
type T = Omit<TermInput, "kind" | "asOf" | "category"> & { category?: string };
const t = ({ category = "Cancer biology", ...x }: T): TermInput => ({ kind: "term", asOf, category, tags: ["theory"], ...x });

export const THEORY_HUB_ID = "theories-of-cancer";

/** Order in which the theories are listed on /mechanics/ and drawn in the hub; the mainstream trunk first, then the challengers, then the newest proposals. */
export const THEORY_IDS = [
  "somatic-mutation-theory", "driver-passenger-model", "clonal-evolution-theory", "hallmarks-synthesis",
  "cancer-stem-cell-theory", "epigenetic-progenitor-theory", "aneuploidy-theory-of-cancer", "metabolic-theory-of-cancer",
  "tissue-organisation-field-theory", "microenvironment-inflammation-theory", "seed-and-soil-hypothesis", "immune-surveillance-immunoediting",
  "ageing-tissue-field-theory", "atavistic-theory-of-cancer", "mechanical-theory-of-cancer", "bioelectric-theory-of-cancer",
] as const;

/** Icon per theory for the /mechanics/ listing (ids from src/components/FrontIcon.tsx). */
export const THEORY_ICONS: Record<string, string> = {
  "somatic-mutation-theory": "targeted-therapy", "driver-passenger-model": "diagnostics", "clonal-evolution-theory": "ai-computation", "hallmarks-synthesis": "drug-discovery",
  "cancer-stem-cell-theory": "cell-therapy", "epigenetic-progenitor-theory": "epigenetics", "aneuploidy-theory-of-cancer": "imaging", "metabolic-theory-of-cancer": "nutrition-lifestyle",
  "tissue-organisation-field-theory": "surgery", "microenvironment-inflammation-theory": "supportive-care", "seed-and-soil-hypothesis": "prevention", "immune-surveillance-immunoediting": "immunotherapy",
  "ageing-tissue-field-theory": "early-detection", "atavistic-theory-of-cancer": "radiopharma", "mechanical-theory-of-cancer": "devices", "bioelectric-theory-of-cancer": "radiation",
};

/** Status word from the closing paragraph of a theory's summary ("Status: partly confirmed. ..."). */
export function theoryStatus(summary: string): string | undefined {
  const m = /Status:\s*(established|partly confirmed|contested|superseded)/i.exec(summary.split("\n\n").at(-1) ?? "");
  return m?.[1].trim();
}

